#!/usr/bin/env python3
"""Build a trade-record strategy's data files from a trade CSV.

Default (no arguments, run from the website repo root):
    python3 .github/scripts/build_trade_data.py
reads  blog/bitcoin-dca-vs-lump-sum/trades.csv
writes apps/bitcoin-dca-calculator/strategies/bitcoin-logbook/bitcoin-logbook-trades.csv      (tradeData columns)
       apps/bitcoin-dca-calculator/strategies/bitcoin-logbook/bitcoin-logbook-trades.meta.json
       apps/bitcoin-dca-calculator/strategies/bitcoin-logbook/bitcoin-logbook-trades.data.js  (generated copy for file://)

Other records:
    python3 .github/scripts/build_trade_data.py SOURCE.csv OUT_DIR STRATEGY_ID

Accepts the Bitcoin Logbook workbook columns
    Date,Side,Amount_USD_or_USDT,BTC_Quantity,Reference_Price_USD,Fee_USD_equivalent,Platform,Fee_Estimated
or a file already in tradeData columns (tradeType,date,amount,amountBTC,atPrice,fee,...).
Validates everything and writes nothing on error (exit 1). Standard library only.
"""
import csv
import hashlib
import io
import json
import os
import sys
from datetime import date

FIELDS = ["tradeType", "date", "amount", "amountBTC", "atPrice", "fee", "platform", "feeEstimated", "note"]
LOGBOOK = {
    "Date": "date", "Side": "tradeType", "Amount_USD_or_USDT": "amount", "BTC_Quantity": "amountBTC",
    "Reference_Price_USD": "atPrice", "Fee_USD_equivalent": "fee", "Platform": "platform", "Fee_Estimated": "feeEstimated",
}
DEFAULT = ("blog/bitcoin-dca-vs-lump-sum/trades.csv",
           "apps/bitcoin-dca-calculator/strategies/bitcoin-logbook", "bitcoin-logbook")


def fail(msg):
    sys.exit("build_trade_data: " + msg)


def number(text):
    """Write numbers without float noise: '1000.0' -> '1000', '0.0146' -> '0.0146'."""
    v = float(text)
    if v < 0:
        raise ValueError("negative")
    return format(v, ".10g") if v != int(v) else str(int(v))


def convert(src):
    with open(src, newline="", encoding="utf-8-sig") as fh:
        rows = list(csv.DictReader(fh))
    if not rows:
        fail(src + " has no trades")
    out, held = [], 0.0
    for line, r in enumerate(rows, 2):
        t = {LOGBOOK.get(k.strip(), k.strip()): (v or "").strip() for k, v in r.items() if k}
        where = f"{src} line {line}"
        t["tradeType"] = t.get("tradeType", "").lower()
        if t["tradeType"] not in ("buy", "sell"):
            fail(f"{where}: side must be Buy or Sell")
        try:
            date.fromisoformat(t.get("date", ""))
        except ValueError:
            fail(f"{where}: bad date {t.get('date')!r}")
        for k in ("amount", "amountBTC", "atPrice", "fee"):
            if t.get(k):
                try:
                    t[k] = number(t[k])
                except ValueError:
                    fail(f"{where}: {k} must be a number >= 0")
        if not t.get("amount") or not t.get("amountBTC"):
            fail(f"{where}: a recorded trade needs both amount and BTC quantity")
        if t.get("feeEstimated"):
            t["feeEstimated"] = {"yes": "true", "no": "false"}.get(t["feeEstimated"].lower(), t["feeEstimated"])
        if out and t["date"] < out[-1]["date"]:
            fail(f"{where}: trades must be in date order")
        held += float(t["amountBTC"]) * (1 if t["tradeType"] == "buy" else -1)
        if held < -1e-12:
            fail(f"{where}: sell of {t['amountBTC']} BTC is more than the BTC held")
        out.append(t)
    return out


def main(argv):
    src, out_dir, sid = argv if len(argv) == 3 else DEFAULT
    if len(argv) not in (0, 3):
        fail("usage: build_trade_data.py [SOURCE.csv OUT_DIR STRATEGY_ID]")
    trades = convert(src)
    buf = io.StringIO()
    w = csv.DictWriter(buf, FIELDS, extrasaction="ignore", lineterminator="\n")
    w.writeheader()
    w.writerows(trades)
    text = buf.getvalue()
    with open(src, "rb") as fh:
        source_sha = hashlib.sha256(fh.read()).hexdigest()
    meta = {
        "strategyId": sid,
        "file": sid + "-trades.csv",
        "description": "Real Bitcoin trades from the Bitcoin Logbook, in tradeData columns.",
        "source": "/" + src.replace(os.sep, "/"),
        "sourceSha256": source_sha,
        "conventions": "amount = USD spent (buy) or received (sell), fee included; amountBTC = BTC actually "
                       "received (buy) or sent (sell); fee (USD) is already inside both and is never deducted again; "
                       "atPrice = reference price recorded with the trade.",
        "firstDate": trades[0]["date"],
        "lastDate": trades[-1]["date"],
        "rows": len(trades),
        "buys": sum(t["tradeType"] == "buy" for t in trades),
        "sells": sum(t["tradeType"] == "sell" for t in trades),
        "sha256": hashlib.sha256(text.encode()).hexdigest(),
    }
    js = ("/* Generated by .github/scripts/build_trade_data.py from " + meta["file"] + ". Do not edit. */\n"
          "(function (root, id, data) {\n"
          "  (root.STRATEGY_DATA = root.STRATEGY_DATA || {})[id] = data;\n"
          "  if (typeof module !== 'undefined' && module.exports) module.exports = data;\n"
          "})(typeof window !== 'undefined' ? window : globalThis, " + json.dumps(sid) + ", "
          + json.dumps({"csv": text, "meta": meta}, ensure_ascii=False) + ");\n")
    base = os.path.join(out_dir, sid + "-trades")
    files = {base + ".csv": text, base + ".meta.json": json.dumps(meta, indent=2) + "\n", base + ".data.js": js}
    for path, content in files.items():
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8", newline="") as fh:
            fh.write(content)
        os.replace(tmp, path)
    print(f"{sid}: {meta['rows']} trades ({meta['buys']} buys, {meta['sells']} sells), "
          f"{meta['firstDate']} -> {meta['lastDate']}, sha256 {meta['sha256'][:12]}")


if __name__ == "__main__":
    main(sys.argv[1:])
